# Rebuild everything in one cell
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from itertools import permutations

n = 11
edges_list = [(u, v) for u in range(n) for v in range(u+1, n)]
E = len(edges_list)
edge_idx = {e: i for i, e in enumerate(edges_list)}

def edge_var(u, v):
    if u > v: u, v = v, u
    return edge_idx[(u,v)] + 1  # 1-indexed

solver = Glucose3()
max_var = [E]

def add_card_clauses(lits, bound, at_least=True):
    if at_least:
        enc = CardEnc.atleast(lits=lits, bound=bound, encoding=EncType.seqcounter, top_id=max_var[0])
    else:
        enc = CardEnc.atmost(lits=lits, bound=bound, encoding=EncType.seqcounter, top_id=max_var[0])
    for clause in enc.clauses:
        solver.add_clause(clause)
        for lit in clause:
            if abs(lit) > max_var[0]:
                max_var[0] = abs(lit)

# Degree constraints: 2 <= deg(v) <= 5
for v in range(n):
    incident = [edge_var(v, u) for u in range(n) if u != v]
    add_card_clauses(incident, 2, at_least=True)
    add_card_clauses(incident, 5, at_least=False)

# No triangles (3-cycles)
for a in range(n):
    for b in range(a+1, n):
        for c in range(b+1, n):
            solver.add_clause([-edge_var(a,b), -edge_var(b,c), -edge_var(a,c)])

# No 4-cycles: no two vertices share 2 common neighbors
for u in range(n):
    for v in range(u+1, n):
        others = [w for w in range(n) if w != u and w != v]
        for i in range(len(others)):
            for j in range(i+1, len(others)):
                w1, w2 = others[i], others[j]
                solver.add_clause([-edge_var(u,w1), -edge_var(v,w1),
                                   -edge_var(u,w2), -edge_var(v,w2)])

# No 5-cycles
seen_5cycles = set()
for perm in permutations(range(n), 5):
    a, b, c, d, e = perm
    cycle = (a, b, c, d, e)
    min_idx = cycle.index(min(cycle))
    rotated = cycle[min_idx:] + cycle[:min_idx]
    if rotated[1] > rotated[-1]:
        rotated = (rotated[0],) + rotated[1:][::-1]
    if rotated in seen_5cycles:
        continue
    seen_5cycles.add(rotated)
    a, b, c, d, e = rotated
    solver.add_clause([-edge_var(a,b), -edge_var(b,c), -edge_var(c,d),
                       -edge_var(d,e), -edge_var(e,a)])

print(f"5-cycle constraints: {len(seen_5cycles)}")
print("Solving...")

result = solver.solve()
print(f"Result: {'SAT' if result else 'UNSAT'}")

if result:
    model = solver.get_model()
    solution_edges = []
    for i, (u, v) in enumerate(edges_list):
        if model[i] > 0:
            solution_edges.append((u, v))

    degrees = [0] * n
    for u, v in solution_edges:
        degrees[u] += 1
        degrees[v] += 1
    print(f"Edges ({len(solution_edges)}): {solution_edges}")
    print(f"Degrees: {degrees}")
    print(f"Degree range: [{min(degrees)}, {max(degrees)}]")
